// Parse the X-Dayjoy-Signature header and verify the HMAC-SHA256 signature.
// Header format:  t=<unix-ts>,v1=<hex-hmac>
// Signed payload:  `<timestamp>.<raw-body-json>`
//
// REPLAY PROTECTION: reject if timestamp is older than 5 minutes.
// TIMING-SAFE COMPARE: prevents timing side-channel attacks.

const header = $json.headers?.['x-dayjoy-signature'] || $json.headers?.['X-Dayjoy-Signature'] || '';
if (!header) {
  return { json: { verified: false, reason: 'missing_signature_header', http_status: 401 } };
}

const parts = {};
header.split(',').forEach(p => {
  const [k, v] = p.split('=');
  parts[k.trim()] = v.trim();
});

const ts = parts['t'];
const sig = parts['v1'];
if (!ts || !sig) {
  return { json: { verified: false, reason: 'malformed_signature_header', http_status: 401 } };
}

// Replay protection — reject anything older than 5 minutes
const now = Math.floor(Date.now() / 1000);
const skew = Math.abs(now - parseInt(ts, 10));
if (skew > 300) {
  return { json: { verified: false, reason: 'timestamp_out_of_window', skew_seconds: skew, http_status: 401 } };
}

// Pull the signing secret from n8n credentials (NOT env vars — env vars leak in workflow JSON)
const webhookSecret = $node['Webhook Secret Credential'].credentials?.webhookSecret ||
                      $credentials?.dayjoyWebhookSigningSecret?.secret;
if (!webhookSecret) {
  return { json: { verified: false, reason: 'missing_signing_secret', http_status: 500 } };
}

// Reconstruct the signed payload:  `<timestamp>.<raw-body>`
const rawBody = typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body);
const signedPayload = `${ts}.${rawBody}`;

// Compute HMAC-SHA256 using Node's crypto module
const crypto = require('crypto');
const computed = crypto.createHmac('sha256', webhookSecret).update(signedPayload).digest('hex');

// Timing-safe comparison
const a = Buffer.from(computed, 'hex');
const b = Buffer.from(sig, 'hex');
const verified = a.length === b.length && crypto.timingSafeEqual(a, b);

return {
  json: {
    verified,
    reason: verified ? 'ok' : 'signature_mismatch',
    timestamp: ts,
    skew_seconds: skew,
    http_status: verified ? 200 : 401
  }
};
